#!/usr/bin/env python3
"""Log statistics utility.

This file implements the command line tool described in SPEC.md.
"""
import sys
import datetime

# Severity order
LEVELS = ["DEBUG", "INFO", "WARN", "ERROR", "FATAL"]
LEVEL_INDEX = {lvl: idx for idx, lvl in enumerate(LEVELS)}

USAGE_ERROR = 2
INPUT_ERROR = 3
MALFORMED_ERROR = 4
SPAN_NO_RECORDS_ERROR = 5
SUCCESS = 0


def usage_error(message="logstat: usage error"):
    sys.stderr.write(message + "\n")
    sys.exit(USAGE_ERROR)


def input_error(message="logstat: cannot read file"):
    sys.stderr.write(message + "\n")
    sys.exit(INPUT_ERROR)


def malformed_error(line_no):
    sys.stderr.write(f"logstat: malformed record on line {line_no}\n")
    sys.exit(MALFORMED_ERROR)


def span_no_records_error():
    sys.stderr.write("logstat: no records matched\n")
    sys.exit(SPAN_NO_RECORDS_ERROR)


# Helpers


def parse_timestamp(ts_str):
    # Expecting exactly 20 chars in format YYYY-MM-DDTHH:MM:SSZ
    try:
        dt = datetime.datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%SZ")
        return dt
    except Exception:
        raise ValueError("invalid timestamp")


# Argument parsing

def parse_args(argv):
    if len(argv) < 2:
        usage_error()
    subcommand = argv[1]
    if subcommand not in ("count", "top", "span"):
        usage_error()
    rest = argv[2:]
    min_level = "DEBUG"
    number = None
    file = None
    i = 0
    while i < len(rest):
        arg = rest[i]
        if arg == "-":
            if file is not None:
                usage_error()
            file = "-"
            i += 1
            continue
        if arg.startswith("-"):
            # Option
            if arg == "--min-level":
                if i + 1 >= len(rest):
                    usage_error()
                val = rest[i + 1]
                i += 2
            elif arg.startswith("--min-level="):
                val = arg[len("--min-level=") :]
                i += 1
            elif arg == "--number":
                if i + 1 >= len(rest):
                    usage_error()
                val = rest[i + 1]
                i += 2
            elif arg.startswith("--number="):
                val = arg[len("--number=") :]
                i += 1
            else:
                usage_error()
            # Validate option values
            if arg.startswith("--min-level"):
                if val not in LEVELS:
                    usage_error()
                min_level = val
            else:  # --number
                if not val.isdigit() or int(val) < 1:
                    usage_error()
                number = int(val)
        else:
            # non-option, should be file
            if file is not None:
                usage_error()
            file = arg
            i += 1
    # Validate that number is only used with top
    if number is not None and subcommand != "top":
        usage_error()
    # Default number for top
    if subcommand == "top" and number is None:
        number = 3
    return subcommand, min_level, number, file


# Main logic

def main():
    subcommand, min_level, number, file = parse_args(sys.argv)
    # Open input
    try:
        if file is None:
            data = sys.stdin.read().splitlines()
        else:
            with open(file, "r", encoding="utf-8") as f:
                data = f.read().splitlines()
    except Exception:
        input_error()

    min_index = LEVEL_INDEX[min_level]

    surviving = []  # list of tuples (timestamp_str, level, service)
    first_malformed_line = None
    for idx, raw_line in enumerate(data, start=1):
        line = raw_line
        # Blank line
        if line.strip(" \t") == "":
            continue
        # Check record
        if line.count("|") < 3:
            first_malformed_line = idx
            break
        parts = line.split("|", 3)
        if len(parts) < 4:
            first_malformed_line = idx
            break
        ts_str, lvl, svc, msg = parts
        # Validate timestamp
        if len(ts_str) != 20:
            first_malformed_line = idx
            break
        try:
            ts = parse_timestamp(ts_str)
        except Exception:
            first_malformed_line = idx
            break
        # Validate level
        if lvl not in LEVELS:
            first_malformed_line = idx
            break
        # Validate service
        if svc == "":
            first_malformed_line = idx
            break
        # Record passes validation
        if LEVEL_INDEX[lvl] >= min_index:
            surviving.append((ts_str, lvl, svc))
    if first_malformed_line is not None:
        malformed_error(first_malformed_line)

    # No malformed, proceed
    if subcommand == "count":
        counts = {lvl: 0 for lvl in LEVELS}
        for _, lvl, _ in surviving:
            counts[lvl] += 1
        total = sum(counts[lvl] for lvl in LEVELS)
        width = len(str(total))
        # Print from min_level up to FATAL
        start_idx = LEVEL_INDEX[min_level]
        for lvl in LEVELS[start_idx:]:
            sys.stdout.write(f"{lvl:<5} {counts[lvl]:>{width}}\n")
        sys.stdout.write(f"{'TOTAL':<5} {total:>{width}}\n")
        sys.exit(SUCCESS)

    if subcommand == "top":
        # Count per service
        svc_counts = {}
        for _, _, svc in surviving:
            svc_counts[svc] = svc_counts.get(svc, 0) + 1
        if not svc_counts:
            sys.exit(SUCCESS)
        # Sort by count desc, then name asc
        sorted_items = sorted(svc_counts.items(), key=lambda x: (-x[1], x[0]))
        # Limit number
        to_print = sorted_items[:number]
        # Determine column widths
        max_name_len = max(len(name) for name, _ in to_print)
        max_count_len = max(len(str(cnt)) for _, cnt in to_print)
        for name, cnt in to_print:
            sys.stdout.write(f"{name:<{max_name_len}} {cnt:>{max_count_len}}\n")
        sys.exit(SUCCESS)

    if subcommand == "span":
        if not surviving:
            span_no_records_error()
        # Extract timestamps
        timestamps = [parse_timestamp(ts) for ts, _, _ in surviving]
        earliest_dt = min(timestamps)
        latest_dt = max(timestamps)
        secs = int((latest_dt - earliest_dt).total_seconds())
        # Print
        sys.stdout.write(f"first {earliest_dt.strftime('%Y-%m-%dT%H:%M:%SZ')}\n")
        sys.stdout.write(f"last  {latest_dt.strftime('%Y-%m-%dT%H:%M:%SZ')}\n")
        sys.stdout.write(f"secs  {secs}\n")
        sys.exit(SUCCESS)


if __name__ == "__main__":
    main()
